    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1

    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1

    max_bitonic = 0
    for i in range(n):
        bitonic_len = inc[i] + dec[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    return n - max_bitonic

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined as a sequence that first strictly increases and then strictly
    decreases (a bitonic sequence). The function finds the length of the longest such subsequence,
    and returns the difference between the total number of students and that length.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    n = len(heights)
    if n == 0:
        return 0

    # Longest increasing subsequence ending at each position
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1

    # Longest decreasing subsequence starting at each position
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1

    # Combine to find the longest bitonic subsequence
    max_len = 0
    for i in range(n):
        bitonic_len = inc[i] + dec[i] - 1  # peak counted twice
        if bitonic_len > max_len:
            max_len = bitonic_len

    return n - max_len

def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    def _bisect_left(a, x):
        lo = 0
        hi = len(a)
        while lo < hi:
            mid = (lo + hi) // 2
            if a[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        return lo

    lis_left = [0] * n
    tails = []
    for i, h in enumerate(heights):
        pos = _bisect_left(tails, h)
        if pos == len(tails):
            tails.append(h)
        else:
            tails[pos] = h
        lis_left[i] = pos + 1

    rev = heights[::-1]
    lis_rev = [0] * n
    tails = []
    for i, h in enumerate(rev):
        pos = _bisect_left(tails, h)
        if pos == len(tails):
            tails.append(h)
        else:
            tails[pos] = h
        lis_rev[i] = pos + 1

    lis_right = [0] * n
    for i in range(n):
        lis_right[i] = lis_rev[n - 1 - i]

    max_len = 0
    for i in range(n):
        l = lis_left[i] + lis_right[i] - 1
        if l > max_len:
            max_len = l

    return n - max_len

def min_groups(w, n, prices):
    prices.sort()
    left, right = 0, n - 1
    groups = 0
    while left <= right:
        if left == right:
            groups += 1
            break
        if prices[left] + prices[right] <= w:
            left += 1
            right -= 1
        else:
            right -= 1
        groups += 1
    return groups
